CREATE TABLE IF NOT EXISTS schema_migrations (filename VARCHAR(255) PRIMARY KEY, applied_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS site_stats (`key` VARCHAR(120) PRIMARY KEY, value BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS admin_users (id VARCHAR(80) PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, display_name VARCHAR(255), password_hash VARCHAR(255), status VARCHAR(30) NOT NULL DEFAULT 'active', created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS roles (id VARCHAR(80) PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, description TEXT, is_system BOOLEAN NOT NULL DEFAULT FALSE, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS permissions (`key` VARCHAR(120) PRIMARY KEY, description TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS user_roles (user_id VARCHAR(80) NOT NULL, role_id VARCHAR(80) NOT NULL, PRIMARY KEY(user_id, role_id), CONSTRAINT fk_user_roles_user FOREIGN KEY(user_id) REFERENCES admin_users(id) ON DELETE CASCADE, CONSTRAINT fk_user_roles_role FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS role_permissions (role_id VARCHAR(80) NOT NULL, permission_key VARCHAR(120) NOT NULL, PRIMARY KEY(role_id, permission_key), CONSTRAINT fk_role_permissions_role FOREIGN KEY(role_id) REFERENCES roles(id) ON DELETE CASCADE, CONSTRAINT fk_role_permissions_permission FOREIGN KEY(permission_key) REFERENCES permissions(`key`) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS admin_sessions (id CHAR(64) PRIMARY KEY, admin_user_id VARCHAR(80) NOT NULL, expires_at VARCHAR(40) NOT NULL, created_at VARCHAR(40) NOT NULL, INDEX idx_admin_sessions_user(admin_user_id), INDEX idx_admin_sessions_expires(expires_at), CONSTRAINT fk_admin_sessions_user FOREIGN KEY(admin_user_id) REFERENCES admin_users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS categories (id VARCHAR(80) PRIMARY KEY, parent_id VARCHAR(80), name VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL UNIQUE, description TEXT, status VARCHAR(30) NOT NULL DEFAULT 'active', sort_order INT NOT NULL DEFAULT 0, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS brands (id VARCHAR(80) PRIMARY KEY, name VARCHAR(255) NOT NULL, slug VARCHAR(255) NOT NULL UNIQUE, description TEXT, status VARCHAR(30) NOT NULL DEFAULT 'active', created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS products (id VARCHAR(80) PRIMARY KEY, name VARCHAR(500) NOT NULL, slug VARCHAR(255) NOT NULL, bearing_number VARCHAR(255) NOT NULL, sku VARCHAR(255) UNIQUE, mpn VARCHAR(255), category_id VARCHAR(80) NOT NULL, brand_id VARCHAR(80), product_type VARCHAR(255) NOT NULL, short_description TEXT, description TEXT, image_key VARCHAR(512), bore_diameter INT, outside_diameter INT, width INT, dimension_unit VARCHAR(20) NOT NULL DEFAULT 'mm', price_minor BIGINT, currency VARCHAR(10) NOT NULL DEFAULT 'BDT', price_visibility VARCHAR(30) NOT NULL DEFAULT 'request', stock_status VARCHAR(50) NOT NULL DEFAULT 'confirm_availability', lead_time_text VARCHAR(255), status VARCHAR(30) NOT NULL DEFAULT 'draft', sort_order INT NOT NULL DEFAULT 0, seo_title VARCHAR(255), meta_description TEXT, version INT NOT NULL DEFAULT 1, created_by VARCHAR(80), updated_by VARCHAR(80), created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, published_at VARCHAR(40), UNIQUE KEY products_category_slug_unique(category_id,slug), INDEX products_status_idx(status), INDEX products_number_idx(bearing_number), CONSTRAINT fk_products_category FOREIGN KEY(category_id) REFERENCES categories(id), CONSTRAINT fk_products_brand FOREIGN KEY(brand_id) REFERENCES brands(id));
CREATE TABLE IF NOT EXISTS product_specifications (id VARCHAR(80) PRIMARY KEY, product_id VARCHAR(80) NOT NULL, `key` VARCHAR(120) NOT NULL, label VARCHAR(255) NOT NULL, value TEXT NOT NULL, unit VARCHAR(50), sort_order INT NOT NULL DEFAULT 0, UNIQUE KEY product_spec_key_unique(product_id,`key`), CONSTRAINT fk_product_specs_product FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS site_settings (`key` VARCHAR(120) PRIMARY KEY, value TEXT NOT NULL, updated_by VARCHAR(80), updated_at VARCHAR(40) NOT NULL);
CREATE TABLE IF NOT EXISTS customers (id VARCHAR(80) PRIMARY KEY, customer_type VARCHAR(30) NOT NULL, full_name VARCHAR(255) NOT NULL, company_name VARCHAR(255), responsible_person_name VARCHAR(255), mobile VARCHAR(50) NOT NULL UNIQUE, email VARCHAR(255) NOT NULL UNIQUE, address TEXT NOT NULL, photo_key VARCHAR(512), document_key VARCHAR(512) NOT NULL, document_type VARCHAR(40) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'pending_review', consent_at VARCHAR(40) NOT NULL, created_at VARCHAR(40) NOT NULL, updated_at VARCHAR(40) NOT NULL, password_hash VARCHAR(255), failed_login_attempts INT NOT NULL DEFAULT 0, locked_until VARCHAR(40), INDEX customers_status_idx(status));
CREATE TABLE IF NOT EXISTS customer_sessions (id CHAR(64) PRIMARY KEY, customer_id VARCHAR(80) NOT NULL, expires_at VARCHAR(40) NOT NULL, created_at VARCHAR(40) NOT NULL, INDEX idx_customer_sessions_customer_id(customer_id), INDEX idx_customer_sessions_expires_at(expires_at), CONSTRAINT fk_customer_sessions_customer FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS customer_password_resets (id VARCHAR(80) PRIMARY KEY, customer_id VARCHAR(80), token_hash VARCHAR(255), expires_at VARCHAR(40), used_at VARCHAR(40), created_at VARCHAR(40), INDEX idx_customer_password_resets_customer(customer_id));
CREATE TABLE IF NOT EXISTS audit_events (id VARCHAR(80) PRIMARY KEY, actor_id VARCHAR(80), actor_email VARCHAR(255) NOT NULL, action VARCHAR(120) NOT NULL, resource_type VARCHAR(120) NOT NULL, resource_id VARCHAR(80), details TEXT, created_at VARCHAR(40) NOT NULL, INDEX audit_created_idx(created_at));
